<template><Card class="s3-manager"><header class="header"><div><h2>核销记录详情</h2><p>一次成功核销对应唯一订单完成事实。</p></div><Button @click="back">返回记录列表</Button></header><Alert v-if="error" type="error">{{error}} <Button type="text" @click="load">重新读取</Button></Alert><Spin v-if="loading" fix/><template v-if="record"><DetailSection title="结果与来源"><FieldRow label="结果">{{label(record.result)}}</FieldRow><FieldRow label="记录编号">{{record.id}}</FieldRow><FieldRow label="店铺">{{record.storeName}}</FieldRow><FieldRow label="来源订单">{{record.orderSn||'拒绝审计未公开订单'}}</FieldRow><FieldRow label="操作者">{{record.operatorName||'名称未提供'}} · {{record.operatorId}}</FieldRow><FieldRow label="发生时间">{{date(record.at)}}</FieldRow><FieldRow label="凭证脱敏引用">{{record.credentialRef||'未提供'}}</FieldRow></DetailSection><DetailSection title="当时点位"><FieldRow label="点位">{{record.point&&record.point.name||record.pointName||'未公开'}}</FieldRow><FieldRow label="地址">{{record.point&&record.point.address||'未公开'}}</FieldRow></DetailSection><DetailSection v-if="record.originalOperation" title="原操作与幂等回执"><p>原操作重试返回这份持久化回执；同一核销只计一次成功事实。</p><FieldRow label="原操作标识">{{record.originalOperation.operationId}}</FieldRow><FieldRow label="回执结果">{{label(record.originalOperation.result.phase)}}</FieldRow><FieldRow label="订单版本">{{record.originalOperation.result.version}}</FieldRow><FieldRow label="原核销记录">{{record.originalOperation.result.verificationId}}</FieldRow><FieldRow label="原完成时间">{{date(record.originalOperation.result.completedAt)}}</FieldRow></DetailSection><Button v-if="record.orderId&&canOrder" @click="order">查看关联订单</Button></template></Card></template>
<script>
import {stage3Read} from '@/api/stage3';import {managerSession} from '@/libs/manager-session';import {managerAccess} from '@/libs/manager-access';import DetailSection from '../p0-stage1/usability/components/DetailSection';import FieldRow from '../p0-stage1/usability/components/FieldRow';import {date,label} from './presentation.cjs';
export default{components:{DetailSection,FieldRow},data(){return {record:null,error:'',loading:false,ticket:0}},computed:{canOrder(){return managerAccess.state.info?.stage1?.stage3?.permissions.includes('order.read')}},mounted(){this.load()},beforeDestroy(){this.ticket++},watch:{'$route.params.id'(){this.record=null;this.load()}},methods:{date,label,back(){this.$router.push({path:'/s3/verifications',query:this.$route.query})},order(){this.$router.push('/s3/orders/'+this.record.orderId)},async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.record=null;this.loading=true;this.error='';try{const result=await stage3Read('/verifications/'+this.$route.params.id);if(ticket===this.ticket&&managerSession.sameSession(owner))this.record=result}catch(e){if(ticket===this.ticket)this.error=e.message}finally{if(ticket===this.ticket)this.loading=false}}}};
</script><style lang="scss">@import './stage3.scss';</style>
